<?php
require_once __DIR__.'/includes/auth.php';require_permission('dashboard');$pdo=db();$logs=$pdo->query('SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 300')->fetchAll();$pageTitle='Audit log';$activePage='audit';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Administration / Accountability</div><h1>Audit log</h1><p>Review who performed protected actions and when.</p></div><span class="view-pill"><i></i> <?= count($logs) ?> events</span></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td class="muted"><?= h(date('M d, Y h:i A',strtotime($log['created_at']))) ?></td><td><?= h($log['full_name']??'System') ?></td><td><span class="status-pill active"><i></i><?= h($log['action']) ?></span></td><td><?= h($log['entity']??'') ?> #<?= h($log['entity_id']??'') ?></td><td><?= h($log['details']??'') ?></td><td class="mono"><?= h($log['ip_address']??'') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
